"""Static, private spot-check gallery generated by a migration dry run."""

from collections import Counter
from datetime import datetime, timedelta, timezone
import hashlib
from html import escape
import json
from pathlib import Path
from urllib.parse import urlsplit

from inventory_detections import bbox_issues, utc_datetime


TRANSITIONS = (
	('Solid fills and doodles · Feb 22', datetime(2026, 2, 22, tzinfo=timezone.utc)),
	('Confidence stored · Jun 12', datetime(2026, 6, 12, tzinfo=timezone.utc)),
	('Separate painting threshold · Jun 13', datetime(2026, 6, 13, tzinfo=timezone.utc)),
	('Explicit flags · Jun 24', datetime(2026, 6, 24, tzinfo=timezone.utc)),
)


def stable_order(row):
	return hashlib.sha256(row['id'].encode()).hexdigest()


def select_samples(candidates, per_side=4, extras=6):
	"""Nearest boundary examples plus a deterministic spread within seven days."""
	selected = {}

	def add(row, label):
		entry = selected.setdefault(row['id'], {**row, 'groups': []})
		if label not in entry['groups']:
			entry['groups'].append(label)

	for title, boundary in TRANSITIONS:
		for side in ('before', 'after'):
			label = f'{title} / {side}'
			pool = [row for row in candidates if row.get('processed_at') is not None
			        and abs(row['processed_at'] - boundary) <= timedelta(days=7)
			        and (row['processed_at'] < boundary) == (side == 'before')]
			pool.sort(key=lambda row: (abs(row['processed_at'] - boundary), row['id']))
			nearest = pool[:min(2, per_side)]
			for row in nearest:
				add(row, label)
			used = {row['id'] for row in nearest}
			spread = sorted((row for row in pool if row['id'] not in used), key=stable_order)
			for row in spread[:per_side - len(nearest)]:
				add(row, label)
	low = []
	bounds = []
	for row in candidates:
		if not row['changes']:
			continue
		objects = row['before'].get('objects') or []
		confidences = [o['confidence'] for o in objects
		               if o.get('confidence') is not None and o['confidence'] < 0.4]
		if confidences:
			low.append((min(0.4 - c for c in confidences), row))
		if any('bbox-exceeds-image' in bbox_issues(o, row['width'], row['height']) for o in objects):
			bounds.append(row)
	low.sort(key=lambda pair: (pair[0], pair[1]['id']))
	for _, row in low[:min(2, extras)]:
		add(row, 'Visible legacy detections (< 0.4)')
	used = {row['id'] for _, row in low[:min(2, extras)]}
	for row in sorted((row for _, row in low if row['id'] not in used), key=stable_order)[:max(0, extras - 2)]:
		add(row, 'Visible legacy detections (< 0.4)')
	for row in sorted(bounds, key=stable_order)[:extras]:
		add(row, 'Boxes exceeding stored dimensions')
	return sorted(selected.values(), key=lambda row: (
		row['processed_at'] or datetime.max.replace(tzinfo=timezone.utc), row['id']))


def web_url(value):
	if not isinstance(value, str):
		return None
	parsed = urlsplit(value)
	return value if parsed.scheme in ('http', 'https') and parsed.netloc else None


def image_variant(sizes):
	"""Prefer an uncropped ordinary 1024-ish rendition; never pick the LLM blackout."""
	if not isinstance(sizes, dict):
		return None
	options = []
	for name, value in sizes.items():
		if not isinstance(value, dict) or not web_url(value.get('url')):
			continue
		if str(name).isdigit():
			options.append((abs(int(name) - 1024), -int(name), str(name), value))
	if options:
		_, _, name, value = min(options, key=lambda item: item[:3])
		return {'name': name, **value}
	full = sizes.get('full')
	if isinstance(full, dict) and web_url(full.get('url')):
		return {'name': 'full', **full}
	return None


def pretty(value):
	return escape(json.dumps(value, indent=2, ensure_ascii=False, sort_keys=True))


def card_html(row):
	before, after = row['before'], row['after']
	objects = after.get('objects') or []
	width, height = row.get('width'), row.get('height')
	valid_dims = type(width) is int and type(height) is int and width > 0 and height > 0
	variant = image_variant(row.get('sizes'))
	full = (row.get('sizes') or {}).get('full') or {}
	full_url = web_url(full.get('url'))
	full_width, full_height = full.get('width'), full.get('height')
	valid_full = all(type(v) is int and v > 0 for v in (full_width, full_height))
	full_is_reversed_photo = valid_dims and valid_full and width != height and (full_width, full_height) == (height, width)
	full_dimensions = f'{full_width} × {full_height}' if valid_full else 'not recorded'
	basis_options = []
	if valid_dims:
		basis_options.append(f'<option value="{width},{height}">Photo row: {width} × {height}</option>')
	if valid_full:
		selected = ' selected' if full_is_reversed_photo or not valid_dims else ''
		basis_options.append(f'<option value="{full_width},{full_height}"{selected}>Full image: {full_width} × {full_height}</option>')
	box_parts = []
	object_rows = []
	for index, obj in enumerate(objects):
		box = obj.get('bbox') or {}
		issues = bbox_issues(obj, width, height)
		blurred = obj.get('blurred') is True
		state = 'blurred' if blurred else 'visible'
		label = f'#{index} {obj.get("class_name") or obj.get("class_id")} · {state}'
		coords = [box.get(k) for k in ('x1', 'y1', 'x2', 'y2')]
		coords_text = f'({coords[0]}, {coords[1]}) → ({coords[2]}, {coords[3]})'
		object_rows.append(f'<tr data-bbox="{escape(json.dumps(coords), quote=True)}"><td>{index}</td><td>{escape(str(obj.get("class_name") or obj.get("class_id")))}</td>'
		                   f'<td>{escape(str(obj.get("confidence", "—")))}</td><td class="{state}">{state}</td>'
		                   f'<td class="original-bbox">{escape(coords_text)}</td>'
		                   '<td class="scaled-bbox">Waiting for image</td><td class="basis-bounds"></td></tr>')
		if (valid_dims or valid_full) and 'bbox-malformed' not in issues:
			x1, y1, x2, y2 = (box[k] for k in ('x1', 'y1', 'x2', 'y2'))
			if x2 > x1 and y2 > y1:
				box_parts.append(f'<g class="{state}"><title>{escape(label)}</title>'
				                 f'<rect x="{x1}" y="{y1}" width="{x2-x1}" height="{y2-y1}"/>'
				                 f'<text x="{x1}" y="{max(14, y1 - 5)}">#{index}</text></g>')
	if variant:
		photo = f'<img loading="lazy" src="{escape(variant["url"], quote=True)}" alt="Photo {escape(row["id"])}">'
	else:
		photo = '<div class="missing">No ordinary image URL in stored sizes.</div>'
	if valid_dims or valid_full:
		basis_width, basis_height = (full_width, full_height) if full_is_reversed_photo or not valid_dims else (width, height)
		photo += f'<svg viewBox="0 0 {basis_width} {basis_height}" preserveAspectRatio="none" aria-label="Detection boxes">{"".join(box_parts)}</svg>'
	links = f'<a href="{escape(variant["url"], quote=True)}" target="_blank" rel="noreferrer">Open rendition</a>' if variant else ''
	if full_url:
		links += f' · <a href="{escape(full_url, quote=True)}" target="_blank" rel="noreferrer">Open full image ({full_dimensions})</a>'
	status = 'Would change · not applied' if row['changes'] else 'Already explicit · unchanged control'
	verdict = 'Behavior checks passed'
	warnings = []
	if full_is_reversed_photo:
		warnings.append(f'Photo-row dimensions are reversed relative to the full image: {width} × {height} vs {full_width} × {full_height}. Viewer defaults to full-image coordinates. Stored boxes are unchanged.')
	elif any('bbox-exceeds-image' in bbox_issues(o, width, height) for o in objects):
		warnings.append('Inventory: some boxes exceed Photo.width/height. Compare full-image dimensions below; changing the viewing basis does not change stored boxes.')
	warning_html = ''.join(f'<p class="warning">{escape(w)}</p>' for w in warnings)
	old_label = 'Old detections · stored in database' if row['changes'] else 'Existing detections · already explicit control'
	new_label = 'New detections · proposed by dry run' if row['changes'] else 'Unchanged detections · no migration applied'
	badges = ''.join(f'<span class="badge">{escape(group)}</span>' for group in row['groups'])
	processed = row['processed_at'].isoformat() if row.get('processed_at') else 'unknown'
	captured = str(row.get('captured_at') or 'unknown')
	return f'''<article class="photo-card" data-id="{escape(row['id'], quote=True)}"
  data-groups="{escape(json.dumps(row['groups']), quote=True)}" data-width="{width or 0}" data-height="{height or 0}">
  <h2>{escape(row['id'])}</h2><div class="badges">{badges}</div>
  <p class="metadata">Processed: {escape(processed)} · Captured: {escape(captured)}<br>
  Photo row: {width} × {height} · <strong>Full image: {full_dimensions}</strong> (sizes.full) · Model: {escape(str(after.get('model_name', 'manual/unknown')))} ·
  {len(objects)} objects · {escape(status)} · {escape(verdict)}</p>{warning_html}
  <div class="review-layout"><div class="visual">
    <div class="photo-controls"><label><input type="checkbox" class="overlay-toggle" checked> Overlay detection boxes</label>
      <label>Box coordinate basis <select class="coordinate-basis" {'disabled' if not basis_options else ''}>{''.join(basis_options) or '<option value="0,0">Unknown dimensions</option>'}</select></label></div>
    <div class="photo-frame">{photo}</div>
    <p class="image-status"></p><p>{links}</p>
    <p class="coordinate-summary"></p>
    <p class="legend"><span class="blurred">Green: blurred</span> · <span class="visible">Orange dashed: deliberately visible</span>. Number = JSON object index.</p>
    <details class="object-list" open><summary>Object list · original and rendition pixels</summary><div class="table-scroll"><table>
      <thead><tr><th>#</th><th>Class</th><th>Confidence</th><th>Decision</th><th>Stored bbox (px)</th><th>Rendition bbox (px)</th><th>Bounds in selected basis</th></tr></thead>
      <tbody>{''.join(object_rows)}</tbody></table></div></details>
    <div class="review-inputs"><label>Review <select class="review-status"><option value="">Unreviewed</option>
      <option value="looks-right">Looks right</option><option value="needs-look">Needs a closer look</option></select></label>
      <label>Notes <textarea class="review-notes" rows="1" placeholder="e.g. box #2 does not line up with the fill"></textarea></label></div>
  </div><div class="json-pair"><section><h3>{old_label}</h3><pre>{pretty(before)}</pre></section>
    <section><h3>{new_label}</h3><pre>{pretty(after)}</pre></section></div></div>
</article>'''


def render_html(rows, source):
	groups = Counter(group for row in rows for group in row['groups'])
	options = ''.join(f'<option value="{escape(group, quote=True)}">{escape(group)} ({count})</option>'
	                  for group, count in groups.items())
	summary = (f'{len(rows)} photos · {sum(row["changes"] for row in rows)} proposed changes · '
	           f'{sum(not row["changes"] for row in rows)} already-explicit controls · {source}')
	template = Path(__file__).with_suffix('.html').read_text()
	return (template.replace('__REPORT_SUMMARY__', escape(summary))
	        .replace('__FILTER_OPTIONS__', options)
	        .replace('__PHOTO_CARDS__', '\n'.join(card_html(row) for row in rows)))


def review_candidate(row, change):
	"""Called only after the dry-run planner has verified the proposed change."""
	if row.get('deleted'):
		return None
	before = json.loads(row['before_text']) if row['before_text'] is not None else None
	if not isinstance(before, dict) or not before.get('objects'):
		return None
	processed_at = utc_datetime(row.get('processed_at'))
	if change is None and (processed_at is None or not any(
		abs(processed_at - boundary) <= timedelta(days=7) for _, boundary in TRANSITIONS
	)):
		return None
	sizes = row.get('sizes')
	if isinstance(sizes, str):
		sizes = json.loads(sizes)
	return {**dict(row), 'sizes': sizes, 'processed_at': processed_at, 'before': before,
	        'after': json.loads(change['after_text']) if change is not None else before,
	        'changes': change is not None}


def write_review(candidates, *, source, output, per_side=4, extras=6):
	selected = select_samples(candidates, per_side, extras)
	if not selected:
		raise ValueError('No reviewable photos found for the transition dates or exception samples')
	output.parent.mkdir(parents=True, exist_ok=True)
	output.write_text(render_html(selected, source))
	return {'output': str(output.resolve()), 'photos': len(selected),
	        'would_change': sum(row['changes'] for row in selected),
	        'controls': sum(not row['changes'] for row in selected),
	        'groups': dict(Counter(group for row in selected for group in row['groups']))}
